import random


class MahjongConnect:
    EMPTY_CELL = ' '

    def __init__(self, BOARD_SIZE, ICONS):
        self.board_size = BOARD_SIZE
        self.icons = ICONS
        self.board = self.create_board()

    def create_board(self):
        rows, cols = self.board_size
        board = [[random.choice(self.icons) for _ in range(cols)] for _ in range(rows)]
        return board

    def is_valid_move(self, pos1, pos2):
        if not self.is_within_bounds(pos1):
            return False
        if not self.is_within_bounds(pos2):
            return False
        if pos1 == pos2:
            return False
        if not self.have_same_icon(pos1, pos2):
            return False
        if not self.has_path(pos1, pos2):
            return False
        return True

    def is_within_bounds(self, pos):
        x, y = pos
        rows, cols = self.board_size
        return 0 <= x < rows and 0 <= y < cols

    def have_same_icon(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        return self.board[x1][y1] == self.board[x2][y2]

    def has_path(self, pos1, pos2):
        visited = set()
        stack = [pos1]

        while stack:
            current_pos = stack.pop()
            if current_pos == pos2:
                return True

            if current_pos in visited:
                continue

            visited.add(current_pos)
            x, y = current_pos

            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                new_x, new_y = x + dx, y + dy
                if self.is_within_bounds((new_x, new_y)):
                    if (new_x, new_y) not in visited and self.board[new_x][new_y] == self.board[x][y]:
                        stack.append((new_x, new_y))

        return False

    def remove_icons(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        self.board[x1][y1] = self.EMPTY_CELL
        self.board[x2][y2] = self.EMPTY_CELL

    def is_game_over(self):
        for row in self.board:
            if any(icon != self.EMPTY_CELL for icon in row):
                return False
        return True
